import { loadVariableFont } from "@remotion/google-fonts/Jost";
import { AbsoluteFill, Easing, Interactive, Sequence, interpolate, spring, useCurrentFrame, useVideoConfig, type InteractiveBaseProps, type InteractiveTransformProps, type InteractivitySchema, type SequenceControls } from "remotion";
import React, { forwardRef, useImperativeHandle, useRef, type ComponentProps } from "react";

const jost = loadVariableFont("normal", { subsets: ["latin"] });

interface AbsorbStackProps {
  lines?: string[];
  accentLine?: number;
  accent?: string;
  /** Text color of the lines; overrides the theme ink. */
  ink?: string;
  background?: string;
  /** Typeface for the lines. Load it yourself; Jost by default. */
  fontFamily?: string;
  fontWeight?: number;
  /** Frames between rings of lines as they settle, center out. */
  stagger?: number;
  /** Size of the stack, around the frame's center. */
  scale?: number;
  /** Frames to hold the first frame before anything moves. */
  delay?: number;
  speed?: number;
  theme?: "dark" | "light";
}

const THEMES = {
  dark: { bg: "#2A1C17", ink: "#E8C9B0", accent: "#C8102E" },
  light: { bg: "#EAD3C3", ink: "#2A1C17", accent: "#C8102E" },
} as const;

const LEADING = 1.02;
const WEIGHT = 400;
const ENTER_LEN = 12;
const SETTLE_AT = 14;
const RING_GAP = 5;
const CLAMP = {
  extrapolateLeft: "clamp",
  extrapolateRight: "clamp",
} as const;
const EASE_OUT = Easing.bezier(0.22, 1, 0.36, 1);

/** The foreground at `scale`, around the frame's center; nothing extra at 1. */
function ScaleLayer({
  scale,
  children,
}: {
  scale: number;
  children: React.ReactNode;
}) {
  if (scale === 1) return children;
  return (
    <AbsoluteFill style={{ transform: `scale(${scale})` }}>
      {children}
    </AbsoluteFill>
  );
}

function AbsorbStackBase({
  lines = ["made to", "sink into", "your cut,", "not sit", "on top."],
  accentLine,
  accent,
  ink: inkProp,
  background,
  fontFamily = jost.fontFamily,
  fontWeight = WEIGHT,
  stagger = RING_GAP,
  scale = 1,
  delay = 0,
  speed = 1,
  theme = "dark",
}: AbsorbStackProps) {
  const frame = Math.max(0, useCurrentFrame() - delay) * speed;
  const { width, height, fps } = useVideoConfig();
  const c = THEMES[theme];
  const hot = accent ?? c.accent;
  const fg = inkProp ?? c.ink;
  const bg = background ?? c.bg;
  const n = Math.max(1, lines.length);
  const hotIndex = accentLine ?? n - 1;

  const fs = Math.min(height * 0.125, width * 0.1);
  const pitch = fs * LEADING;
  const mid = (n - 1) / 2;
  const centreY = height * 0.5;
  const spreadPitch = n > 1 ? (height * 0.84) / (n - 1) : 0;

  return (
    <AbsoluteFill style={{ background: bg, overflow: "hidden" }}>
      <ScaleLayer scale={scale}>
        {lines.map((line, i) => {
          const offset = i - mid;
          const ring = Math.abs(offset);
          const enter = interpolate(
            frame,
            [ring * 3, ring * 3 + ENTER_LEN],
            [0, 1],
            {
              ...CLAMP,
              easing: EASE_OUT,
            },
          );
          const settle = spring({
            frame: frame - SETTLE_AT - ring * stagger,
            fps,
            config: { damping: 20, stiffness: 70, mass: 1 },
          });
          const from = centreY + offset * spreadPitch;
          const to = centreY + offset * pitch;
          const y = from + (to - from) * settle;
          const drift = interpolate(
            enter,
            [0, 1],
            [offset >= 0 ? 0.25 : -0.25, 0],
          );
          const sat = interpolate(settle, [0, 1], [72, 100], CLAMP);
          const ink = i === hotIndex ? hot : fg;
          return (
            <div
              key={`${i}-${line}`}
              style={{
                position: "absolute",
                left: 0,
                right: 0,
                top: y - pitch / 2,
                height: pitch,
                display: "flex",
                alignItems: "center",
                justifyContent: "center",
                fontFamily,
                fontWeight,
                fontSize: fs,
                lineHeight: 1,
                letterSpacing: "-0.025em",
                textTransform: "lowercase",
                whiteSpace: "pre",
                color: `color-mix(in oklab, ${ink} ${sat.toFixed(1)}%, ${bg})`,
                opacity: enter,
                transform: `translateY(${(drift * fs).toFixed(2)}px)`,
              }}
            >
              {line}
            </div>
          );
        })}
      </ScaleLayer>
    </AbsoluteFill>
  );
}

const elementSchema = {
  ...Interactive.baseSchema,
  theme: {
    type: "enum",
    default: "dark",
    variants: {
      dark: {},
      light: {},
    },
    description: "Theme",
  },
  fontWeight: {
    type: "number",
    default: 400,
    min: 100,
    max: 900,
    step: 100,
    description: "Weight",
    hiddenFromList: false,
  },
  stagger: {
    type: "number",
    default: 5,
    min: 0,
    max: 15,
    step: 1,
    description: "Ring stagger",
    hiddenFromList: false,
  },
  accent: {
    type: "color",
    default: undefined,
    description: "Accent",
  },
  fontFamily: {
    type: "font-family",
    default: "Jost",
    description: "Font",
  },
  ink: {
    type: "color",
    default: undefined,
    description: "Text color",
  },
  background: {
    type: "color",
    default: undefined,
    description: "Background",
  },
  scale: {
    type: "number",
    default: 1,
    min: 0.5,
    max: 1.5,
    step: 0.05,
    description: "Scale",
    hiddenFromList: false,
  },
  delay: {
    type: "number",
    default: 0,
    min: 0,
    max: 60,
    step: 1,
    description: "Delay (frames)",
    hiddenFromList: false,
  },
  speed: {
    type: "number",
    default: 1,
    min: 0.25,
    max: 4,
    step: 0.25,
    description: "Speed",
    hiddenFromList: false,
  },
  ...Interactive.transformSchema,
} as const satisfies InteractivitySchema;

const ELEMENT_PROP_KEYS = new Set(["theme","fontWeight","stagger","accent","fontFamily","ink","background","scale","delay","speed"]);

const ELEMENT_PROP_DEFAULTS: Record<string, unknown> = {
  theme: "dark",
  fontWeight: 400,
  stagger: 5,
  fontFamily: "Jost",
  scale: 1,
  delay: 0,
  speed: 1,
};

type AbsorbStackElementProps = InteractiveBaseProps &
  InteractiveTransformProps &
  ComponentProps<typeof AbsorbStackBase>;

const AbsorbStackInner = forwardRef<
  HTMLDivElement,
  AbsorbStackElementProps & { readonly controls: SequenceControls | undefined }
>(({ controls, name, style, ...rest }, ref) => {
  const outlineRef = useRef<HTMLDivElement>(null);
  useImperativeHandle(ref, () => outlineRef.current as HTMLDivElement, []);
  const componentProps: Record<string, unknown> = { ...ELEMENT_PROP_DEFAULTS };
  const sequenceProps: Record<string, unknown> = {};
  for (const [key, value] of Object.entries(rest)) {
    if (ELEMENT_PROP_KEYS.has(key)) {
      if (value !== undefined) componentProps[key] = value;
    } else {
      sequenceProps[key] = value;
    }
  }
  return (
    <Sequence
      layout="none"
      {...sequenceProps}
      controls={controls}
      name={name ?? "<AbsorbStack>"}
      outlineRef={outlineRef}
    >
      <div
        ref={outlineRef}
        style={{
          position: "relative",
          width: "100%",
          height: "100%",
          display: "flex",
          alignItems: "center",
          justifyContent: "center",
          ...style,
        }}
      >
        <AbsorbStackBase
          {...(componentProps as unknown as ComponentProps<typeof AbsorbStackBase>)}
        />
      </div>
    </Sequence>
  );
});

export const AbsorbStack = Interactive.withSchema({
  Component: AbsorbStackInner,
  componentName: "<AbsorbStack>",
  componentIdentity: null,
  schema: elementSchema,
  supportsEffects: false,
});
